#include "modules.h"
#include <string.h>

const char *const fm_outputs[3] = {
    "src/common/scDefinitions/sc_fiesta_module_tokens.h",
    "src/SerialConfigurator/src/core/sc_module_table.h",
    "src/common/scripts/fiesta-modules.sh"};
/* Retain the public launcher name and generated bytes during migration. */
static const char note[] =
    "Generated by scripts/fiesta_modules.py from modules.json. Do not edit.";
static void tokens(fm_context *c, const fm_registry *r, jb_string_t *out) {
  fm_printf(
      c, out,
      "/* %s */\n#pragma once\n\n/* clang-format off */\n#ifdef "
      "__cplusplus\nextern \"C\" {\n#endif\n\n"
      "/* Number of modules handled by SerialConfigurator. */\n#define "
      "SC_MODULE_COUNT %zuu\n\n"
      "/* Module tokens: debug prefix, SerialConfigurator HELLO and firmware\n"
      " * manifests. Modules outside SerialConfigurator keep theirs here too, "
      "so\n"
      " * no token is reused by accident. */\n",
      note, r->sc_count);
  for (size_t i = 0; i < r->count; ++i)
    if (r->modules[i].firmware) {
      fm_printf(c, out, "#define SC_MODULE_TOKEN_%s ", r->modules[i].macro);
      fm_literal(c, out, r->modules[i].token);
      fm_append(c, out, "\n");
    }
  fm_append(c, out, "\n/* Names shown by SerialConfigurator. */\n");
  for (size_t i = 0; i < r->sc_count; ++i) {
    fm_printf(c, out, "#define SC_MODULE_%s ", r->sc[i]->macro);
    fm_literal(c, out, r->sc[i]->display);
    fm_append(c, out, "\n");
  }
  fm_append(c, out, "\n#ifdef __cplusplus\n}\n#endif\n/* clang-format on */\n");
}
static void table(fm_context *c, const fm_registry *r, jb_string_t *out) {
  fm_printf(
      c, out,
      "/* %s */\n#pragma once\n\n#include <stdbool.h>\n#include <stddef.h>\n\n"
      "#include \"sc_fiesta_module_tokens.h\"\n\n/* clang-format off */\n"
      "/* One X(token, display_name, source_dir, tests, tests_drive) row per "
      "module,\n"
      " * in module index order. The index is part of the saved flash-path "
      "schema.\n"
      " * tests: the firmware runs functional tests; tests_drive: their "
      "status\n"
      " * carries the demanded and measured actuator position. */\n#define "
      "SC_MODULE_TABLE(X) \\\n",
      note);
  for (size_t i = 0; i < r->sc_count; ++i) {
    const fm_module *m = r->sc[i];
    if (i)
      fm_append(c, out, " \\\n");
    if (m->firmware)
      fm_printf(c, out, "  X(SC_MODULE_TOKEN_%s, ", m->macro);
    else
      fm_append(c, out, "  X(NULL, ");
    fm_printf(c, out, "SC_MODULE_%s, ", m->macro);
    if (m->firmware)
      fm_literal(c, out, m->name);
    else
      fm_append(c, out, "NULL");
    fm_printf(c, out, ", %s, %s)", m->tests ? "true" : "false",
              m->tests_drive ? "true" : "false");
  }
  fm_append(
      c, out,
      "\n\n/* NULL-terminated by-id name fragments of Fiesta boards that\n"
      " * SerialConfigurator does not talk to. */\n#define "
      "SC_OUT_OF_SCOPE_BY_ID_HINTS {");
  for (size_t i = 0; i < r->count; ++i)
    if (r->modules[i].firmware && !r->modules[i].sc) {
      fm_literal(c, out, r->modules[i].hint);
      fm_append(c, out, ", ");
    }
  fm_append(c, out, "NULL}\n/* clang-format on */\n");
}
static void shell_quote(fm_context *c, jb_string_t *out, const char *text) {
  bool plain = *text != '\0';
  for (const unsigned char *p = (const unsigned char *)text; *p; ++p)
    plain &= (*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
             (*p >= '0' && *p <= '9') || strchr("_@%+=:,./-", *p) != NULL;
  if (plain) {
    fm_append(c, out, text);
    return;
  }
  fm_append(c, out, "'");
  for (const char *p = text; c->status == HAL_OK && *p; ++p)
    if (*p == '\'')
      fm_append(c, out, "'\"'\"'");
    else
      fm_status(c, jb_string_append(out, p, 1));
  fm_append(c, out, "'");
}
static void shell(fm_context *c, const fm_registry *r, jb_string_t *out) {
  static const char *const comments[] = {
      "Firmware modules, in registry order.",
      "Host test builds as name:source_dir:build_dir.",
      "Modules whose host build has the check-cppcheck target."};
  static const char *const names[] = {"FIESTA_FIRMWARE_MODULES",
                                      "FIESTA_HOST_TEST_MODULES",
                                      "FIESTA_CPPCHECK_MODULES"};
  fm_printf(c, out, "# %s\n# shellcheck shell=bash\n", note);
  for (size_t group = 0; group < COUNTOF(names); ++group) {
    fm_printf(c, out, "\n# %s\n%s=(\n", comments[group], names[group]);
    for (size_t i = 0; i < r->count; ++i) {
      const fm_module *m = &r->modules[i];
      if ((group == 0 && !m->firmware) || (group == 1 && !m->host_tests) ||
          (group == 2 && !m->cppcheck))
        continue;
      jb_string_t value = {0};
      fm_string(&value);
      if (group == 1)
        fm_printf(c, &value, "%s:src/%s:src/%s/%s", m->name, m->name, m->name,
                  m->host_tests);
      else
        fm_append(c, &value, m->name);
      fm_append(c, out, "    ");
      shell_quote(c, out, jb_string_data(&value));
      fm_append(c, out, "\n");
      jb_string_destroy(&value);
    }
    fm_append(c, out, ")\n");
  }
  fm_append(c, out, "\nfiesta_module_token_for() {\n    case \"$1\" in\n");
  for (size_t i = 0; i < r->count; ++i)
    if (r->modules[i].firmware) {
      fm_append(c, out, "        ");
      shell_quote(c, out, r->modules[i].name);
      fm_append(c, out, ") printf '%s\\n' ");
      shell_quote(c, out, r->modules[i].token);
      fm_append(c, out, " ;;\n");
    }
  fm_append(c, out, "        *) return 1 ;;\n    esac\n}\n");
}
void fm_render(fm_context *c, const fm_registry *r, jb_string_t out[3]) {
  if (c->status != HAL_OK)
    return;
  tokens(c, r, &out[0]);
  table(c, r, &out[1]);
  shell(c, r, &out[2]);
}
void fm_report(fm_context *c, const fm_registry *r, const jb_string_t out[3],
               jb_string_t *json) {
  fm_append(c, json, "{\"schemaVersion\":1,\"modules\":[");
  for (size_t i = 0; i < r->count; ++i) {
    if (i)
      fm_append(c, json, ",");
    fm_append(c, json, "{\"definition\":");
    fm_format(c, json, r->modules[i].definition);
    fm_append(c, json, ",\"byIdHint\":");
    fm_json(c, json, r->modules[i].hint);
    fm_append(c, json, "}");
  }
  fm_append(c, json, "],\"outputs\":{");
  for (size_t i = 0; i < COUNTOF(fm_outputs); ++i) {
    if (i)
      fm_append(c, json, ",");
    fm_json(c, json, fm_outputs[i]);
    fm_append(c, json, ":");
    fm_json(c, json, jb_string_data(&out[i]));
  }
  fm_append(c, json, "}}\n");
}
